1341	                "url": { "type": "string", "default": "https://api.example.com/v1/slots" },
1342	                "method": { "type": "string", "default": "POST" },
1343	                "headers": { "type": "object", "properties": { "Content-Type": { "type": "string", "default": "application/json" } } },
1344	                "body": {
1345	                  "type": "object",
1346	                  "properties": {
1347	                    "treatment": { "type": "string", "default": "{{treatment}}" },
1348	                    "day": { "type": "string", "default": "{{wanted_day}}" }
1349	                  }
1350	                }
